// Use unique numeric ids and a Map to store the current timeout handle per interval.
// Node's setTimeout returns an object, so we hand out our own numbers instead.
const intervalMap = new Map(); // id -> current timeout handle
let nextId = 1;

/**
 * @param {Function} fn
 * @param {number} delay
 * @param {number} period
 * @return {number} id
 */
function customInterval(fn, delay, period) {
    const id = nextId++;
    let count = 0;

    const schedule = () => {
        // Wait is delay + period * count (grows linearly)
        const handle = setTimeout(() => {
            fn();
            // fn may have cleared this interval; only reschedule if still active
            if (!intervalMap.has(id)) return;
            count++;
            schedule();
        }, delay + period * count);
        intervalMap.set(id, handle);
    };

    schedule();
    return id;
}

/**
 * @param {number} id
 * @return {void}
 */
function customClearInterval(id) {
    if (intervalMap.has(id)) {
        clearTimeout(intervalMap.get(id));
        intervalMap.delete(id);
    }
}
